'use strict';
window.Catalogue={validate(data){if(!data||typeof data.shopName!=='string'||!data.shopName.trim()||data.shopName.length>80||!Array.isArray(data.products)||data.products.length>200)throw Error('Invalid catalogue: provide a shop name and up to 200 products.');for(const key of ['instagram','tiktok']){if(data[key]&&!this.social(data[key],key))throw Error('Use a valid '+key+' profile URL.');}if(data.phone&&!/^\+?[1-9]\d{6,14}$/.test(data.phone))throw Error('Use an international phone number, e.g. +60123456789.');const ids=new Set();for(const p of data.products){if(!p||typeof p.id!=='string'||ids.has(p.id)||typeof p.name!=='string'||!p.name.trim()||p.name.length>150||!['Tops','Dresses','Sets'].includes(p.category)||(p.price!==null&&(typeof p.price!=='number'||!Number.isFinite(p.price)||p.price<0))||!Array.isArray(p.sizes)||!p.sizes.length||!Array.isArray(p.colors)||!p.colors.length||[...p.sizes,...p.colors].some(x=>typeof x!=='string'||!x.trim()||x.length>80)||typeof p.description!=='string'||p.description.length>3000||!this.image(p.image))throw Error('Invalid product information. Check names, category, price, sizes, colours and image.');if(p.quantity!=null&&(!Number.isSafeInteger(p.quantity)||p.quantity<0||p.quantity>1000000))throw Error('Quantity must be a whole number from 0 to 1,000,000, or blank for unknown availability.');if(p.imageViews!==undefined&&(!p.imageViews||typeof p.imageViews!=='object'||Array.isArray(p.imageViews)||!this.image(p.imageViews.front)||p.imageViews.front!==p.image||Object.entries(p.imageViews).some(([key,src])=>!['front','back','both'].includes(key)||!this.image(src))))throw Error('Check front, back and both-view photos.');if(p.images!==undefined&&(!Array.isArray(p.images)||p.images.length>12||p.images.some(src=>!this.image(src))))throw Error('Invalid product gallery.');ids.add(p.id);}return data;},image(url){return typeof url==='string'&&/^(assets|uploads)\/[a-zA-Z0-9_./-]+$/.test(url)&&!url.includes('..');},social(value,kind){try{const u=new URL(value);return u.protocol==='https:'&&(u.hostname===kind+'.com'||u.hostname==='www.'+kind+'.com')&&!u.username&&!u.password?u.href:null;}catch{return null;}},async load(){let apiError;try{const response=await fetch('api.php?action=catalogue',{cache:'no-store'});if(!response.ok)throw Error('Server unavailable');const data=this.validate(await response.json());return {data,live:true};}catch(e){apiError=e;}const response=await fetch('catalogue.json',{cache:'no-store'});if(!response.ok)throw Error('The collection could not be loaded. Please try again.');return {data:this.validate(await response.json()),live:false};},stock(product){return product.quantity==null?'Availability on request':product.quantity===0?'Sold out':product.quantity+' left';},money(value){if(value===null)return 'Ask for price';return new Intl.NumberFormat('en-MY',{style:'currency',currency:'MYR',minimumFractionDigits:0,maximumFractionDigits:2}).format(value);}};
